	ys, th, yo := splitTiles(p.Height, tileSize, tileOverlap, r)
	xs, tw, xo := splitTiles(p.Width, tileSize, tileOverlap, r)
	p.TileH, p.TileW, p.YOverlaps, p.XOverlaps = th/r, tw/r, yo, xo
	for _, y := range ys {
