	} `json:"tensors"`
}

func loadEncRef(t *testing.T) *encManifest {
	t.Helper()
	buf, err := os.ReadFile(filepath.Join(encRef, "manifest.json"))
	if err != nil {
		t.Skipf("no reference dump in %s (%v); run reference/dump_h3_textenc.py", encRef, err)
